tool_input.command:
$f = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions\session-36640a2f-f155-4de4-95e3-78c170d4bfe1.json"
$j = Get-Content $f -Raw -Encoding utf8 | ConvertFrom-Json
Write-Output "=== rows 类型/数量 ==="; $j.record.rows.GetType().Name; $j.record.rows.Count
Write-Output "=== rows 键(若对象) 或首个元素 ==="; 
if($j.record.rows -is [System.Array]){ $j.record.rows[0].PSObject.Properties.Name } else { $j.record.rows.PSObject.Properties.Name }
Write-Output "=== 搜 rows 里 toolTokens/contextHeaders ==="
$j.record.rows.PSObject.Properties.Name | Where-Object { $_ -match 'tool|token|header|break|context' }

$pc = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
Write-Output "=== 15:22:59(重启)之后更新的会话文件 ==="
Get-ChildItem $pc -Filter "session-*.json" | Where-Object { $_.LastWriteTime -gt [datetime]"2026-11-14 15:22:59" } | Sort-Object LastWriteTime -Descending | Select-Object Name,LastWriteTime | Format-Table -AutoSize
Write-Output "=== 各会话 agentPreset 与 toolsTokens (近期5个) ==="
Get-ChildItem $pc -Filter "session-*.json" | Sort-Object LastWriteTime -Descending | Select-Object -First 5 | ForEach-Object {
  try { $j = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json; $preset=$j.record.rows.agentPreset.val; $tt=$j.record.rows.contextBreakdown.val.breakdown.toolsTokens; $tc=$j.record.rows.contextHeaders.val.headers[0].tools.Count; "$($_.Name.Substring(0,20)): preset=$preset tools=$tc toolsTokens=$tt (mtime $($_.LastWriteTime.ToString('HH:mm:ss')))" } catch { "$($_.Name): parse err" }
}

$pc = "$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
foreach($n in @("session-36640a2f-f155-4de4-95e3-78c170d4bfe1","session-70d2180c-a0a4-47f6-a7b7-444aa8ff2bde","session-39e84ea8-c9fa-4831-883f-b1cfb4aa42a8")){
  $j = Get-Content "$pc\$n.json" -Raw -Encoding utf8 | ConvertFrom-Json
  $id = $j.record.identity
  Write-Output "$($n.Substring(0,20)): identity=$($id | ConvertTo-Json -Compress)"
}

$restart = [datetime]"2026-11-14 15:22:59"
foreach($t in @(1794636555616,1794637062196,1794624630976)){
  $dt = [DateTimeOffset]::FromUnixTimeMilliseconds($t).ToLocalTime().DateTime
  $flag = if($dt -gt $restart){"【重启后新建】"}else{"(重启前)"}
  Write-Output "$t => $($dt.ToString('yyyy-MM-dd HH:mm:ss')) $flag"
}
Write-Output "重启时间: $($restart.ToString('HH:mm:ss'))"
